style.css:
@-moz-document domain("duolingo.com") {
/* =========================================================
   CONFIGURAÇÕES
   ========================================================= */

:root {
    --old-green: #58cc02;
    --old-green-dark: #46a302;
    --old-blue: #1cb0f6;
    --old-blue-dark: #1899d6;
    --old-orange: #ff9600;
    --old-red: #ff4b4b;
    --old-purple: #ce82ff;

    --tree-background: #f7f7f7;
    --card-white: #ffffff;
    --border-gray: #dedede;
    --text-dark: #3c3c3c;
}

/* =========================================================
   FUNDO
   ========================================================= */

html,
body {
    background: var(--tree-background) !important;
}

main {
    background: var(--tree-background) !important;
}

/* =========================================================
   ESCONDER ELEMENTOS MAIS "MODERNOS"
   ========================================================= */

/* Personagens decorativos */

main img[alt*="character"],
main img[alt*="personagem"] {
    opacity: 0.15 !important;
}

/* Alguns elementos de decoração */

main [data-test*="character"] {
    opacity: 0.2 !important;
}

/* =========================================================
   CABEÇALHO
   ========================================================= */

header {
    background: #ffffff !important;
    border-bottom: 2px solid var(--border-gray) !important;
    box-shadow: 0 2px 5px rgba(0,0,0,.08) !important;
}

/* =========================================================
   ÁREA PRINCIPAL
   ========================================================= */

main > div {
    max-width: 1000px !important;
}

/* =========================================================
   UNIDADES
   ========================================================= */

main section {
    background: transparent !important;
}

/* Cartões de unidades */

main section > div {
    border-radius: 12px !important;
}

/* =========================================================
   CÍRCULOS DA TRILHA
   ========================================================= */

/*
   Tenta transformar os elementos circulares
   em algo parecido com as antigas habilidades.
*/

main button {
    border-radius: 12px !important;
}

/* Círculos grandes */

main button[data-test*="skill"],
main button[data-test*="lesson"],
main [data-test*="skill"] button,
main [data-test*="lesson"] button {
    width: 76px !important;
    height: 76px !important;

    border-radius: 50% !important;

    border: 4px solid var(--old-green-dark) !important;

    background: var(--old-green) !important;

    box-shadow:
        0 5px 0 var(--old-green-dark),
        0 8px 12px rgba(0,0,0,.15) !important;

    transition:
        transform .15s ease,
        box-shadow .15s ease !important;
}

/* =========================================================
   HOVER
   ========================================================= */

main button[data-test*="skill"]:hover,
main button[data-test*="lesson"]:hover,
main [data-test*="skill"] button:hover,
main [data-test*="lesson"] button:hover {
    transform: translateY(-3px) !important;

    box-shadow:
        0 8px 0 var(--old-green-dark),
        0 12px 16px rgba(0,0,0,.16) !important;
}

/* =========================================================
   CAMINHO
   ========================================================= */

/*
   Dá um visual de caminho vertical entre as atividades.
*/

main [data-test*="path"],
main [class*="path"] {
    background: transparent !important;
}

/* =========================================================
   BOTÕES
   ========================================================= */

button {
    font-family:
        "Arial",
        "Helvetica Neue",
        sans-serif !important;

    font-weight: 700 !important;
}

/* Botões verdes */

button[data-test*="start"],
button[data-test*="continue"] {
    background: var(--old-green) !important;

    border: 2px solid var(--old-green-dark) !important;

    border-bottom-width: 5px !important;

    border-radius: 12px !important;

    color: white !important;
}

/* =========================================================
   CARDS
   ========================================================= */

main [class*="card"] {
    background: var(--card-white) !important;

    border: 2px solid var(--border-gray) !important;

    border-radius: 12px !important;

    box-shadow:
        0 2px 5px rgba(0,0,0,.08) !important;
}

/* =========================================================
   TEXTOS
   ========================================================= */

main h1,
main h2,
main h3 {
    color: var(--text-dark) !important;

    font-family:
        "Arial",
        "Helvetica Neue",
        sans-serif !important;
}

main p,
main span {
    font-family:
        "Arial",
        "Helvetica Neue",
        sans-serif !important;
}

/* =========================================================
   BARRAS DE PROGRESSO
   ========================================================= */

[role="progressbar"] {
    background: #e5e5e5 !important;

    border-radius: 20px !important;

    overflow: hidden !important;
}

[role="progressbar"] > div {
    background: var(--old-green) !important;

    border-radius: 20px !important;
}

/* =========================================================
   ÍCONES / MEDALHAS
   ========================================================= */

main svg {
    transition: transform .15s ease !important;
}

main svg:hover {
    transform: scale(1.05);
}

/* =========================================================
   ESTILO ANTIGO PARA MODAIS
   ========================================================= */

[role="dialog"] {
    background: white !important;

    border-radius: 16px !important;

    border: 2px solid var(--border-gray) !important;

    box-shadow:
        0 10px 30px rgba(0,0,0,.2) !important;
}

/* =========================================================
   MENU INFERIOR
   ========================================================= */

nav {
    background: #ffffff !important;

    border-top: 2px solid var(--border-gray) !important;

    box-shadow:
        0 -2px 8px rgba(0,0,0,.08) !important;
}

/* =========================================================
   EFEITO "APP ANTIGO"
   ========================================================= */

button,
[role="button"] {
    transition:
        filter .15s ease,
        transform .15s ease !important;
}

button:active,
[role="button"]:active {
    transform: translateY(2px) !important;
}

/* =========================================================
   CORES DE STATUS
   ========================================================= */

/* Verde = concluído */

[data-test*="completed"] button {
    background: var(--old-green) !important;
    border-color: var(--old-green-dark) !important;
}

/* Azul = conteúdo especial */

[data-test*="story"] button,
[data-test*="practice"] button {
    background: var(--old-blue) !important;
    border-color: var(--old-blue-dark) !important;
}

/* Laranja = desafio */

[data-test*="challenge"] button {
    background: var(--old-orange) !important;
    border-color: #d77d00 !important;
}

/* Vermelho = erro/perigo */

[data-test*="locked"] button {
    background: #eeeeee !important;
    border-color: #cccccc !important;
}

/* =========================================================
   SOMBRAS ANTIGAS
   ========================================================= */

button,
[role="button"],
main [class*="card"] {
    box-sizing: border-box !important;
}

/* =========================================================
   FIM
   ========================================================= */
}
